<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_access();$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT p.*,a.kode_anggota,COALESCE(s.nama,g.nama) nama,s.nis,s.nisn FROM perpustakaan_peminjaman p JOIN perpustakaan_anggota a ON a.id=p.anggota_id LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id WHERE p.id=?");$st->execute([$id]);$p=$st->fetch();if(!$p)exit('Transaksi tidak ditemukan.');$st=$pdo->prepare("SELECT d.*,b.kode_buku,b.judul,e.kode_eksemplar FROM perpustakaan_detail_peminjaman d JOIN perpustakaan_buku b ON b.id=d.buku_id LEFT JOIN perpustakaan_eksemplar e ON e.id=d.eksemplar_id WHERE d.peminjaman_id=? ORDER BY d.id");$st->execute([$id]);$details=$st->fetchAll();$page_title='Detail Peminjaman';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Detail Peminjaman</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-journal-text"></i> <?=e($p['nomor_transaksi'])?></h1><p><?=e($p['nama'])?> · <?=e($p['kode_anggota'])?></p></div><div><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/peminjaman.php"><i class="bi bi-arrow-left"></i> Kembali</a><a class="btn btn-primary" href="<?=BASE_URL?>perpustakaan/pengembalian.php?peminjaman_id=<?=$id?>"><i class="bi bi-arrow-return-left"></i> Proses Pengembalian</a></div></div><div class="form-card"><div class="detail-grid"><div><small>Anggota</small><strong><?=e($p['nama'])?></strong></div><div><small>Kode</small><strong><?=e($p['kode_anggota'])?></strong></div><div><small>Tanggal Pinjam</small><strong><?=e($p['tanggal_pinjam'])?></strong></div><div><small>Jatuh Tempo</small><strong><?=e($p['tanggal_jatuh_tempo'])?></strong></div><div><small>Status</small><strong><?=e(perpus_label_status(perpus_effective_loan_status($p)))?></strong></div><div><small>Catatan</small><strong><?=e($p['catatan']??'-')?></strong></div></div></div><div class="form-card"><h5>Daftar Buku</h5><div class="table-responsive"><table class="data-table"><thead><tr><th>Buku</th><th>Jumlah</th><th>Status</th><th>Tanggal Kembali</th><th>Kondisi</th></tr></thead><tbody><?php foreach($details as $d):?><tr><td><?=e($d['judul'])?><div class="text-muted small"><?=e($d['kode_eksemplar']?:$d['kode_buku'])?></div></td><td><?=number_format((int)$d['jumlah'])?></td><td><?=e(perpus_label_status($d['status']))?></td><td><?=e($d['tanggal_kembali']??'-')?></td><td><?=e($d['kondisi_kembali']??'-')?></td></tr><?php endforeach;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';
